preConditionHook:
// Breakaway move, shallow pullback, break (Brian's phone notes P11, p. 28).
// H = highest high of bars 1..maxRun+maxPullback (ties keep the most recent,
// strict el_gt scan), at tHi. Move (Brian 2026-11-05): consecutive bull bars,
// each with range >= k x the ATR as of that bar, ending at tHi, at most maxRun,
// at least minRunBars; height = H - open of the oldest run bar. Pullback = bars
// 1..tHi-1, minPullback..maxPullback of them, none reaching H, none below
// H - f x height. LONG on the close above H; short mirrors. Not
// BreakoutPullbackEntry (no top-fraction bound, breaks the pullback high).
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, SwingLowRejection's
// block verbatim -- seeded with a full N-term sum on the first calculated bar or
// when the length changes, and after that TWO statements (S += in; S -= out;) --
// EL evaluates S[1] + in - out left to right. It stays in the hook, which the
// generator emits unconditionally.
if (atrLenState != (int)atrLookback) {
    atrSum = 0.0;
    for (aa = 0; aa < (int)atrLookback; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLookback;
} else {
    outIdx = (int)atrLookback;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLookback;
// EL reads atrValue[k], the VARIABLE's own history: 0 for every bar before the
// strategy's first evaluated one, the stored value after. Mirrored as a growing
// history (StochasticCross's push_back form), so atrHist[size-1-k] is atrValue[k]
// and k past the start reads 0 -- and an input change mid-run never discards it,
// as a resized ring buffer would.
atrHist.push_back(atrValue);
fireLong = false;
fireShort = false;
winN = (int)maxRun + (int)maxPullback;
tHi = 1;
tLo = 1;
for (ii = 2; ii <= winN; ++ii) {
    if (el_gt(high[ii], high[tHi])) tHi = ii;
    if (el_lt(low[ii], low[tLo])) tLo = ii;
}
if (tHi - 1 >= (int)minPullback && tHi - 1 <= (int)maxPullback) {
    runHi = 0;
    sHi = tHi;
    onRun = true;
    for (ii = tHi; ii <= tHi + (int)maxRun - 1; ++ii) {
        atrIdx = (int)atrHist.size() - 1 - (ii);
        barAtr = atrIdx >= 0 ? atrHist[(std::size_t)atrIdx] : 0.0;
        if (onRun && el_gt(close[ii], open[ii]) && el_ge(high[ii] - low[ii], k * barAtr)) {
            runHi = runHi + 1;
            sHi = ii;
        } else {
            onRun = false;
        }
    }
    heightHi = high[tHi] - open[sHi];
    pbOk = true;
    for (ii = 1; ii <= tHi - 1; ++ii) {
        if (el_ge(high[ii], high[tHi]) || el_lt(low[ii], high[tHi] - f * heightHi)) pbOk = false;
    }
    if (runHi >= (int)minRunBars && pbOk && el_gt(close[0], high[tHi])) fireLong = true;
}
if (tLo - 1 >= (int)minPullback && tLo - 1 <= (int)maxPullback) {
    runLo = 0;
    sLo = tLo;
    onRun = true;
    for (ii = tLo; ii <= tLo + (int)maxRun - 1; ++ii) {
        atrIdx = (int)atrHist.size() - 1 - (ii);
        barAtr = atrIdx >= 0 ? atrHist[(std::size_t)atrIdx] : 0.0;
        if (onRun && el_lt(close[ii], open[ii]) && el_ge(high[ii] - low[ii], k * barAtr)) {
            runLo = runLo + 1;
            sLo = ii;
        } else {
            onRun = false;
        }
    }
    heightLo = open[sLo] - low[tLo];
    pbOk = true;
    for (ii = 1; ii <= tLo - 1; ++ii) {
        if (el_le(low[ii], low[tLo]) || el_gt(high[ii], low[tLo] + f * heightLo)) pbOk = false;
    }
    if (runLo >= (int)minRunBars && pbOk && el_lt(close[0], low[tLo])) fireShort = true;
}
